*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//#include("../js/controlResize.js"); // 화면 리사이징

scwin.vScrenID = "ULDINS26600.xml";
scwin.cnt = 0;
scwin.prevRow = -1;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 다운로드IP체크  목록 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    //데이터셋 초기화
    dts_List.removeAll();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS26600_VIEW_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.download.select.listDownloadIpChkInquiry" + "&{P}IP_ADDR=" + txb_pIP_ADDR.getValue() + "&{P}PROCS_DD_SDATE=" + edt_pPROCS_DD_SDATE.getValue() + "&{P}PROCS_DD_EDATE=" + edt_pPROCS_DD_EDATE.getValue();
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    cmb_ACTIV_YN.setDisabled(false);
};



/********************************************** 
 * 함수명   : fn_new
 * 설명       :  조회버튼 클릭시 신규등록을 위한 dataset 세팅 
 ***********************************************/
scwin.fn_new = function() {
    dts_List.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ULDINS26600_VIEW_OUT";
    dts_List.reset();
    dts_List.insertRow();
    var toDay = $c.ut.cGetToday("yyyymmdd");
    edt_PROCS_DD.setValue(toDay);
    fn_CtrlBtn_temp("insert");
    $c.stf.setObjectValue(cmb_ACTIV_YN, "Y");
    cmb_ACTIV_YN.setDisabled(true);
    txb_IP_ADDR.setDisabled(false);
    $c.stf.setObjectValue(cmb_DNLD_GRP_TP_CD, "01");
    if (document.getElementById("btn_file")) {
        btn_file.setDisabled(true); // 첨부파일
        btn_file.src = "../img/ins/btn_file_d.gif";
    }

    //중복체크버튼
    $c.stf.showObj(btn_dupl, true);
    txb_dupl.setValue("N");
};


/********************************************** 
 * 함수명   : ins_process	
 * 설명       : 다운로드IP체크 정보를 저장 , 수정 한다. screenProcsTpCd 02,03
 ***********************************************/
scwin.ins_process = function(screenProcsTpCd) {
    if (screenProcsTpCd == '02') {
        // 저장

        if (edt_PROCS_DD.getValue() == "" || edt_PROCS_DD.text.indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "등록일"));
            edt_PROCS_DD.focus();
            return false;
        }
        if (txb_IP_ADDR.getValue() == "" || txb_IP_ADDR.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "IP"));
            txb_IP_ADDR.focus();
            return false;
        }
        if (txb_dupl.value == "N") {
            $c.win.alert('IP중복체크를 확인해주세요.');
            txb_IP_ADDR.focus();
            return false;
        }
        if (!confirm('다운로드IP체크 정보를 저장 하시겠습니까?')) {
            return false;
        }
        trs_save.Action = "/DownLoadInfoAction.do?method=registerDownLoadIpChk" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + screenProcsTpCd;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_List)";
        trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
        trs_save.Post();
    }
    if (screenProcsTpCd == '03') {
        // 수정

        if (!$c.cp.isModified(dts_List)) {
            $c.win.alert("변경된 데이터가 없습니다.");
            return;
        }
        if (edt_PROCS_DD.getValue() == "" || edt_PROCS_DD.text.indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "등록일"));
            edt_PROCS_DD.focus();
            return false;
        }
        if (txb_IP_ADDR.getValue() == "" || txb_IP_ADDR.getValue().indexOf(" ") == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-A005", "IP"));
            txb_IP_ADDR.focus();
            return false;
        }
        if (!confirm('다운로드IP체크 정보를 수정 하시겠습니까?')) {
            return false;
        }
        trs_save.Action = "/DownLoadInfoAction.do?method=modifyDownLoadIpChk" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + screenProcsTpCd;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_List)";
        trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
        trs_save.Post();
    }
    if (screenProcsTpCd == '04') {
        // 삭제

        dts_List.setCellData(dts_List.getRowPosition(), "CRDUSTATUS", $c.ut.cGetToday("yyyymmddhhmmss"));
        if (!confirm('다운로드IP체크 정보를 삭제 하시겠습니까?')) {
            return false;
        }
        trs_save.Action = "/DownLoadInfoAction.do?method=removeDownLoadIpChk" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + screenProcsTpCd;
        trs_save.KeyName = "toinb_dataid4";
        trs_save.KeyValue = "JSP(I:pInput=dts_List)";
        trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
        trs_save.Post();
    }
};




/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달값을 정의한다.
 ***********************************************/
scwin.arrPar = new Array();
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // 표준코드 OR 발행기관 코드      
    scwin.arrPar[1] = txb_param2.getValue();

    //alert(arrPar[0] + " " + arrPar[1]);
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************** 
 * 함수명   : fn_check_dupl
 * 설명       : IP 중복검사 한다.
 ***********************************************/
scwin.fn_check_dupl = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS26600_VIEW_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.download.select.duplDownloadIpChk" + "&{P}IP_ADDR=" + txb_IP_ADDR.getValue();

    // alert(url);
    dts_Simbol.DataID = encodeURI(url);
    dts_Simbol.reset();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    fn_CtrlBtn_temp("no_data");

    //fn_setFromToDate(1, edt_pPROCS_DD_SDATE, edt_pPROCS_DD_EDATE);	

    $c.stf.showObj(txb_param1, false);
    $c.stf.showObj(txb_param2, false);
    $c.stf.showObj(txb_dupl, false);
    ins_combo_set(dts_DNLD_GRP_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "04204", "NODEFAULT"); //다운로드그룹구분
    $c.stf.showObj(btn_dupl, false);
};
scwin.btn_file_onclick = function() {
    /*
    txb_param1 에는 신청ID
    txb_param2 에는 구분값을 넣는데.. 
     + "1 : 발행기관신청, 팩스-발행기관신청 \n"
     + "2 : 표준코드신청, 팩스-표준코드신청 \n"
     + "3 : 팩스-다운로드IP 로 값을 넣어주세요.\n"
     */
    txb_param1.setValue(txb_IP_ADDR.getValue()); // IP_ADDR
    txb_param2.setValue("3");
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS91100", "첨부파일", "655", "350");
};
scwin.img_PROCS_DD_onclick = function() {
    popUpCalendar2(edt_PROCS_DD);
};
scwin.trs_save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "다운로드IP체크 관리"));
    scwin.ins_search();
};
scwin.trs_save_OnFail = function() {
    alert_tr_error(trs_save);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    scwin.cnt = rowcount;
    if (scwin.cnt == 0) fn_CtrlBtn_temp("no_data");
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리

    $c.stf.showObj(btn_dupl, false);
    txb_dupl.setValue("N");
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    scwin.cnt = 0;
    $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	
    fn_CtrlBtn_temp("no_data");
};
scwin.dts_List_OnRowPosChanged = function(row) {
    if (dts_List.getRowStatus(row) == 1) return;
    dts_List.undoRow(scwin.prevRow);
    scwin.prevRow = row;
    fn_CtrlBtn_temp("update");
    txb_IP_ADDR.setDisabled(true);
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.btn_new_onclick = function() {
    scwin.fn_new();
};
scwin.btn_save_onclick = function() {
    scwin.ins_process("02");
};
scwin.btn_modify_onclick = function() {
    scwin.ins_process("03");
};
scwin.btn_delete_onclick = function() {
    scwin.ins_process("04");
};
scwin.img_pPROCS_DD_SDATE_onclick = function() {
    popUpCalendar2(edt_pPROCS_DD_SDATE);
};
scwin.img_pPROCS_DD_EDATE_onclick = function() {
    popUpCalendar2(edt_pPROCS_DD_EDATE);
};
scwin.txb_pIP_ADDR_onkeyup = function() {
    if (txb_pIP_ADDR.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        } else {

        }
    }
};
scwin.btn_dupl_onclick = function() {
    if (txb_IP_ADDR.getValue() == "" || txb_IP_ADDR.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "IP"));
        txb_IP_ADDR.focus();
        return;
    }
    scwin.fn_check_dupl();
};
scwin.dts_Simbol_OnLoadCompleted = function(rowcount) {
    if (rowcount == 0) {
        $c.win.alert(" 사용할 수 있습니다. [ IP 중복 체크 ]");
        txb_dupl.setValue("Y");
    } else {
        $c.win.alert(" 이미 사용 중 입니다.  [ IP 중복 체크 ]");
        txb_dupl.setValue("N");
    }
};
